var o=`0429-pytt-i-panna`;var t=`world-0429`;var i=`SE`;var a=`northern-europe`;var s=4;var r=32;var d={en:`Pytt i Panna`,ua:`Пютт-і-панна`};var g={en:`A traditional dish from Sweden, centered on potato, yellow onion, smoked ham, fresh pork sausage. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Швеція. Основні складники: картопля, жовта цибуля, копчена шинка, сира свиняча ковбаса. Домашній варіант із кількостями продуктів за етапами приготування.`};var u=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`potato`,550,`g`],[`yellow-onion`,180,`g`],[`sunflower-oil`,45,`ml`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 11 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 11 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:11,i:[[`smoked-ham`,280,`g`],[`fresh-pork-sausage`,260,`g`]]},{en:`Boil the eggs for about 7 minutes, cool promptly in cold water, peel and prepare as required.`,ua:`Варіть яйця приблизно 7 хвилин, швидко охолодіть у холодній воді, очистьте та підготуйте за потреби.`,t:[`hard-boiling-eggs`],m:7,i:[[`chicken-egg`,4,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`parsley`,18,`g`],[`fermented-cucumber`,130,`g`]]}];var l={slug:o,id:t,country:`SE`,region:a,servings:4,minutes:32,title:d,text:g,steps:u};export{i as country,l as default,t as id,r as minutes,a as region,s as servings,o as slug,u as steps,g as text,d as title};